# Built/tested on the named-palette UX release e84cc2c. Only the listed files change.
from pathlib import Path
import base64, hashlib, json, zlib
DATA = """"""
records = json.loads(zlib.decompress(base64.b64decode(DATA)))
prepared = []
for item in records:
    path = Path(item['path'])
    crlf = path.exists() and b'\r\n' in path.read_bytes()
    if item['before'] is None:
        if path.exists(): raise RuntimeError('New file already exists: ' + str(path))
        content = item['content']
    else:
        original = path.read_text(encoding='utf-8')
        if hashlib.sha256(original.encode()).hexdigest() != item['before']:
            raise RuntimeError('UX baseline changed: ' + str(path))
        lines = original.splitlines(keepends=True)
        for start, end, replacement in reversed(item['edits']):
            lines[start:end] = replacement
        content = ''.join(lines)
    if hashlib.sha256(content.encode()).hexdigest() != item['after']:
        raise RuntimeError('Patch verification failed: ' + str(path))
    prepared.append((path, content, crlf))
for path, content, crlf in prepared:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content.replace('\n', '\r\n').encode() if crlf else content.encode())
print('Installed tested brush and Preview changes:', len(records), 'files; named-palette UX preserved.')
